// Un cargador de módulos de juguete, al estilo CommonJS.
// Cada «archivo» es una función que recibe require, module y exports (el envoltorio que Node arma por detrás).
const archivos = {
  './pedidos.js': (require, module, exports) => {
    console.log('  [pedidos] empieza');
    const envio = require('./envio.js');            // acá se dispara la carga de envio.js
    exports.IVA = 0.21;
    exports.total = (neto, kg) => Math.round(neto * (1 + exports.IVA) + envio.costo(kg));
    console.log('  [pedidos] termina');
  },
  './envio.js': (require, module, exports) => {
    console.log('  [envio] empieza');
    const pedidos = require('./pedidos.js');        // ciclo: pedidos todavía no terminó
    console.log('  [envio] ve pedidos.IVA =', pedidos.IVA);
    exports.costo = kg => 1800 + 150 * Math.max(0, kg - 1);
    console.log('  [envio] termina');
  },
};

const cache = {};                                   // ruta -> module
function require_(ruta) {
  if (cache[ruta]) return cache[ruta].exports;      // ya cargado (o a medio cargar): se devuelve lo que haya
  const module = { exports: {} };
  cache[ruta] = module;                             // se anota ANTES de ejecutar: así se corta el bucle
  archivos[ruta](require_, module, module.exports);
  return module.exports;
}

